/**
 * The runtime mount function. 
 * It takes a generated component (which is just a function returning a DOM element right now)
 * and attaches it to a container on the actual web page.
 * 
 * @param {Function} component - The render function generated by our compiler
 * @param {HTMLElement} container - The HTML element to put our component inside
 */
export function mount(component, container) {
  // Clear out anything already inside the container
  container.innerHTML = '';
  
  // Call the component's render function to get the actual DOM element
  const element = component();
  
  // Attach that element to the page container
  container.appendChild(element);
}
